-- New admin-curated template: "Determining Relative Density of Metal Samples by Spring Extension"
-- (O-Level Physics Practical Workbook, Item 10 - six 100g metal "gold-lookalike" samples M1-M6,
-- tested to see which (if any) are consistent with pure silver). A bespoke 3D scene
-- (VirtualLabSceneSilverDensity.vue, render_component 'silver_density_spring') reuses the existing
-- retort_stand/spring/ruler/beaker/mass_piece models - the same tall, shoulder-height retort stand
-- and spring-and-pointer rig as Hooke's Law, Pendulum and Titration (same proportions, no apparatus
-- of its own). A thread carries the hanging metal the rest of the way down to a beaker standing
-- directly on the bench - the same role the real apparatus's 20cm thread plays - so no riser block
-- is needed; immersing a sample lowers it further down that same thread, into the water.
--
-- Physics: the student first measures a reference (unloaded) pointer position once, reused for
-- every sample. Each 100g sample then gives roughly the same air reading (so e_a = air - reference
-- is roughly constant across all six - itself worth noticing), but a different upthrust once
-- immersed depending on the sample's own density, so the water reading (and e_w) varies. Relative
-- density by the loss-of-weight method: R.D. = e_a / (e_a - e_w), density = 1000 x R.D. (kg/m3) -
-- compared against pure silver's 10200-10500 kg/m3 range. Each metal's true density is a hidden
-- constant in the Vue component (TRUE_DENSITY_KGM3), the same "hidden value graded against" approach
-- as the concave mirror's true focal length; three of the six are genuine silver, three are not, so
-- the class discussion has a real answer either way.
--
-- Each trial (a raw air reading then a raw water reading for one metal, both against the one shared
-- reference reading) is paired client-side in VirtualLabExperiment.vue
-- (lastDensityAirCm/lastDensityWaterCm/lastDensityReferenceCm/lastDensityMetalKey) into one Results
-- Table row, same pattern as the concave mirror's u/v pairing. The graph plots density against metal
-- number - with only six discrete samples rather than a continuously varying quantity, a line of
-- best fit through the origin doesn't apply here the way it does for the other physics graphs, but a
-- scatter of each sample's density immediately shows which ones fall inside the silver band.

INSERT INTO `virtual_lab_experiments`
    (`title`, `subject_id`, `topic`, `category`, `difficulty`, `created_by`, `objective`, `introduction`, `apparatus`, `materials`, `safety_precautions`, `scene_objects`, `conclusion_prompt`, `marks`, `is_template`, `status`, `render_mode`, `render_component`)
VALUES (
    'Determining Relative Density of Metal Samples by Spring Extension', (SELECT id FROM subjects WHERE name = 'PHY' LIMIT 1), 'Density and Relative Density', 'physics', 'intermediate', NULL,
    'To determine the relative density (and hence the density) of six metal samples by the loss-of-weight method, and use it to decide which are consistent with pure silver.',
    'A group of students on a trip picked up some rare-looking metals that looked like gold, and argued about whether they were worth a fortune or not. One of them suggested testing them in the school laboratory instead of guessing. As one of the students, you will hang each 100g sample (labelled M1 to M6) from a spring on a thread, and read the pointer''s position against a rule - first with nothing attached (the reference reading), then with the sample hanging in air, then with it fully immersed in water. Because the upthrust in water depends on the sample''s volume - and so on its density - the readings let you calculate each sample''s relative density (R.D. = e_a / (e_a - e_w)) and its density in kg/m3, without ever weighing it on a balance. Pure silver has a density of 10200 to 10500 kg/m3 - use your results to advise your friends which samples, if any, are consistent with being silver.',
    '1 retort stand with clamp, 1 spring with a pointer, 1 metre rule, a thread, 1 beaker of water, 6 metal samples (M1-M6) each of mass 100g.',
    'None (all apparatus is simulated).',
    'Lower each sample gently until it is fully immersed without touching the sides or bottom of the beaker; let the pointer become stationary before reading it; read the pointer with your eye level with the scale, to avoid parallax error; handle the beaker of water carefully.',
    '[{"key":"stand1","object_type":"retort_stand","position":{"x":-1.2,"y":0,"z":0},"in_tray":true},{"key":"spring1","object_type":"spring","position":{"x":-1.2,"y":0,"z":0.6},"props":{"natural_length_cm":10,"spring_constant_n_per_m":5},"in_tray":true},{"key":"rule1","object_type":"ruler","position":{"x":1.2,"y":0,"z":0},"in_tray":true},{"key":"beaker1","object_type":"beaker","position":{"x":0.8,"y":0,"z":0.6},"props":{"color":"#bcd9f2"},"in_tray":true},{"key":"metal1","object_type":"mass_piece","position":{"x":0.2,"y":0,"z":1.0},"props":{"mass_g":100},"in_tray":true},{"key":"metal2","object_type":"mass_piece","position":{"x":0.45,"y":0,"z":1.0},"props":{"mass_g":100},"in_tray":true},{"key":"metal3","object_type":"mass_piece","position":{"x":0.7,"y":0,"z":1.0},"props":{"mass_g":100},"in_tray":true},{"key":"metal4","object_type":"mass_piece","position":{"x":0.95,"y":0,"z":1.0},"props":{"mass_g":100},"in_tray":true},{"key":"metal5","object_type":"mass_piece","position":{"x":1.2,"y":0,"z":1.0},"props":{"mass_g":100},"in_tray":true},{"key":"metal6","object_type":"mass_piece","position":{"x":1.45,"y":0,"z":1.0},"props":{"mass_g":100},"in_tray":true}]',
    'Based on your results, which of the six metal samples (M1-M6) are consistent with pure silver? Explain how the spring-extension method let you tell them apart even though they are all the same mass and look identical.',
    20.00, 1, 'published', '2d', 'silver_density_spring'
);

SET @density_id = (SELECT id FROM `virtual_lab_experiments` WHERE `title` = 'Determining Relative Density of Metal Samples by Spring Extension' AND `is_template` = 1 ORDER BY id DESC LIMIT 1);

