INSERT INTO `virtual_lab_questions` (`experiment_id`, `question_number`, `question_text`, `question_type`, `stage`, `requirement`, `linked_to_graph`, `marks`) VALUES
(@density_id, 1, 'For each metal sample, show your calculation of e_a = air reading - reference, e_w = water reading - reference, relative density R.D. = e_a / (e_a - e_w), and density = 1000 x R.D. (kg/m3). Check these match the values your Results Table filled in automatically.', 'calculation', 'after_experiment', 'notebook_only', 0, 6.00),
(@density_id, 2, 'Pure silver has a density of 10200 to 10500 kg/m3. Using your graph, state which of the six metal samples (M1-M6), if any, are consistent with pure silver, and advise your friends accordingly.', 'short_answer', 'after_experiment', 'notebook_only', 1, 6.00),
(@density_id, 3, 'All six samples have the same mass (100g) and gave roughly the same reading in air, yet their readings in water were different. Explain why.', 'short_answer', 'after_experiment', 'notebook_only', 0, 5.00),
(@density_id, 4, 'State one precaution you took when immersing a sample in the water, and explain why it matters.', 'short_answer', 'after_experiment', 'notebook_only', 0, 3.00);
